insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('7a734263-0e57-554d-ae98-6d89f509556d', 'e4b4abea-0bf2-5180-affe-2a0ac83e65e7', 'f4c81869-c3cc-50d3-a177-dabf0bad1718', null, 'Identify two factors of production.', '["Profit and revenue","Labour and capital","Shares and loans","Prices and wages"]'::jsonb, 'Land, labour, capital and enterprise are the four factors of production.', false, 'paper', '1.1 Business activity', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('7a734263-0e57-554d-ae98-6d89f509556d', 1, '''Identify'' = name them, no explanation needed. The four factors are land, labour, capital and enterprise. Careful: capital means man-made resources (machines, buildings), not money.') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('fddfadd5-3528-5157-a1fe-526ce8cb5ab3', 'e4b4abea-0bf2-5180-affe-2a0ac83e65e7', 'f4c81869-c3cc-50d3-a177-dabf0bad1718', null, 'Define ''opportunity cost''.', '["The total amount of money that is spent on making a decision","The cost of all the resources a business has ever used","The next best alternative given up when a choice is made","The extra cost of producing one more unit of a product"]'::jsonb, 'Opportunity cost is the benefit of the next best alternative that was given up.', false, 'paper', '1.1 Business activity', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('fddfadd5-3528-5157-a1fe-526ce8cb5ab3', 2, 'A definition must be precise: ''the next best alternative given up''. Saying ''the cost of something'' or giving only the money spent scores 0. Add an example if there''s a second mark.') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('6fb585b4-080c-5971-a55b-9ca635b822e0', 'e4b4abea-0bf2-5180-affe-2a0ac83e65e7', 'f4c81869-c3cc-50d3-a177-dabf0bad1718', null, 'A café buys coffee beans for $1 and sells each coffee for $4. Explain how the café adds value.', '["It pays its workers more than other cafés in the area","It turns cheap inputs into a product customers pay more for","It spends nothing at all on rent, wages or electricity","It buys its coffee beans from the cheapest supplier"]'::jsonb, 'Added value = $4 − $1 = $3: the café''s brand, service and setting make customers pay more than the cost of the beans.', false, 'paper', '1.1 Business activity', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('6fb585b4-080c-5971-a55b-9ca635b822e0', 1, 'Define added value (selling price − cost of bought-in materials = $3 here), then APPLY: how this café makes customers pay more (brand, comfortable seating, service, location). Remember added value is not the same as profit.') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('37e6d45a-7987-5ccb-a13f-a88e83edbf3c', 'e4b4abea-0bf2-5180-affe-2a0ac83e65e7', 'f4c81869-c3cc-50d3-a177-dabf0bad1718', null, 'What is meant by specialisation?', '["Workers or businesses concentrating on what they do best","One worker doing every task needed to make a product","A business selling as many different products as possible","A business producing goods only for the government"]'::jsonb, 'Specialisation means focusing on one task or product, which raises efficiency.', false, 'paper', '1.1 Business activity', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('37e6d45a-7987-5ccb-a13f-a88e83edbf3c', 0, 'Define it, then for ''explain an advantage'' link it to the business: faster output and better skills → higher productivity → lower costs. Disadvantage: boring work, and production stops if one stage fails.') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('b59c8360-655f-5f53-afbd-e5872e1e4ea3', 'e4b4abea-0bf2-5180-affe-2a0ac83e65e7', 'f4c81869-c3cc-50d3-a177-dabf0bad1718', null, 'Which of these businesses is in the secondary sector?', '["A sugar refinery","A transport firm","A sugar-cane farm","A supermarket"]'::jsonb, 'A refinery manufactures sugar from cane, so it is secondary. The farm is primary; shops and transport are tertiary.', false, 'paper', '1.2 Economic sectors', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('b59c8360-655f-5f53-afbd-e5872e1e4ea3', 0, 'Primary = extracting raw materials, secondary = manufacturing and construction, tertiary = services. In ''identify the sector'' questions, give the sector AND the reason (it turns raw materials into products).') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('d5032bb6-2a4c-51b7-a11a-430436d34eb1', 'e4b4abea-0bf2-5180-affe-2a0ac83e65e7', 'f4c81869-c3cc-50d3-a177-dabf0bad1718', null, 'Explain why the tertiary sector has become more important in many countries.', '["Governments have banned most manufacturing firms","Fewer people now want to buy services of any kind","Rising incomes mean people spend more on services","Factories have moved into the primary sector instead"]'::jsonb, 'Higher incomes increase demand for services, so the tertiary sector grows (Mauritius moved from sugar to tourism and finance).', false, 'paper', '1.2 Economic sectors', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('d5032bb6-2a4c-51b7-a11a-430436d34eb1', 2, 'Give a reason and develop it: as incomes rise, people spend more on services such as tourism, banking and leisure, so more businesses and jobs move into services. Other valid reasons: better education, technology, cheaper manufacturing abroad.') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('7084e408-6b51-57d8-a7dd-1b0b07c1431a', 'e4b4abea-0bf2-5180-affe-2a0ac83e65e7', 'f4c81869-c3cc-50d3-a177-dabf0bad1718', null, 'Which statement about the public sector is correct?', '["It includes all of the public limited companies","It is owned and controlled by the government","It is owned by shareholders who buy shares","Its main aim is always to maximise profit"]'::jsonb, 'The public sector is government-owned. A plc is private: its shares are just sold to the public.', false, 'paper', '1.2 Economic sectors', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('7084e408-6b51-57d8-a7dd-1b0b07c1431a', 1, 'A common trap: a public limited company (plc) is in the PRIVATE sector, because private shareholders own it. The public sector is government-owned (e.g. state utilities, public hospitals).') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('ec39acec-f507-5737-adc0-7f752095d005', 'e4b4abea-0bf2-5180-affe-2a0ac83e65e7', 'f4c81869-c3cc-50d3-a177-dabf0bad1718', null, 'Identify a reason why an entrepreneur writes a business plan.', '["To avoid paying any business tax","To guarantee the business will profit","To make the business a public company","To persuade a bank to lend money"]'::jsonb, 'Lenders want to see a plan before they lend, so a plan helps raise finance.', false, 'paper', '1.3 Enterprise, growth and size', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('ec39acec-f507-5737-adc0-7f752095d005', 3, 'Reasons that score: to obtain finance (banks want to see a plan), to set objectives and give direction, to identify risks and plan for them. For ''explain'', link it to the case (e.g. the owner needs a $20 000 loan).') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('4ee6b60d-8dcc-55bd-a6ae-8077d90f21ea', 'e4b4abea-0bf2-5180-affe-2a0ac83e65e7', 'f4c81869-c3cc-50d3-a177-dabf0bad1718', null, 'Why is profit not a good way to measure the size of a business?', '["Profit cannot be measured until the business closes","Profit is always the same as the number of employees","A large business can make a small profit or a loss","Small businesses are not allowed to make any profit"]'::jsonb, 'Profit shows performance, not size: big firms can make losses and small firms can be very profitable.', false, 'paper', '1.3 Enterprise, growth and size', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('4ee6b60d-8dcc-55bd-a6ae-8077d90f21ea', 2, 'Explain the flaw: profit depends on costs and how well the business performs that year, not on how big it is. A large firm can make a loss; a small one can be very profitable. Valid measures: employees, revenue, capital employed, market share.') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('f07be782-d347-583b-a611-f6e119a429a5', 'e4b4abea-0bf2-5180-affe-2a0ac83e65e7', 'f4c81869-c3cc-50d3-a177-dabf0bad1718', null, 'A clothing manufacturer buys the shops that sell its clothes. What type of integration is this?', '["Backward vertical integration","Conglomerate integration","Horizontal integration","Forward vertical integration"]'::jsonb, 'Buying the shops moves the manufacturer forward along the chain, towards the customer.', false, 'paper', '1.3 Enterprise, growth and size', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('f07be782-d347-583b-a611-f6e119a429a5', 3, 'Use the supply chain: supplier → manufacturer → retailer → customer. Moving towards the customer = forward vertical; towards the supplier = backward vertical; same stage = horizontal; unrelated = conglomerate. Then give a benefit (control over how products are sold, keeping the retailer''s profit).') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('2088dd5d-836b-52c5-a629-e627d1ea8917', 'e4b4abea-0bf2-5180-affe-2a0ac83e65e7', 'f4c81869-c3cc-50d3-a177-dabf0bad1718', null, 'Give a reason why some businesses stay small.', '["The owner wants to keep control and offer a personal service","The government does not allow small businesses to grow","Small businesses always make more profit than big ones","Small businesses can never borrow any money from banks"]'::jsonb, 'Many owners choose to stay small to keep control and give customers a personal service.', false, 'paper', '1.3 Enterprise, growth and size', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('2088dd5d-836b-52c5-a629-e627d1ea8917', 0, 'Reasons that score: the owner''s choice (control, less stress), a small or niche market, a personal service (hairdresser, tutor), or a lack of finance to grow. For ''explain'', link it to the business in the question.') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('6146a90e-7718-5263-a92b-423b2eca1f6f', 'e4b4abea-0bf2-5180-affe-2a0ac83e65e7', 'f4c81869-c3cc-50d3-a177-dabf0bad1718', null, 'Explain one reason why a new business might fail.', '["It sets clear objectives early on","It writes a detailed business plan","It has too many loyal customers","It runs out of cash to pay its bills"]'::jsonb, 'A business can be profitable and still fail if it can''t pay its bills on time.', false, 'paper', '1.3 Enterprise, growth and size', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('6146a90e-7718-5263-a92b-423b2eca1f6f', 3, 'Reasons that score: poor management, lack of finance or cash flow problems, poor planning, strong competition, changes in the market. Develop it: running out of cash means suppliers and wages can''t be paid, so the business has to close even if it is profitable.') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation, battle_ok, source, ref, difficulty) values ('95a1a2e7-fb5e-52f2-a553-e456aa46eea3', 'e4b4abea-0bf2-5180-affe-2a0ac83e65e7', 'f4c81869-c3cc-50d3-a177-dabf0bad1718', null, 'What is meant by ''limited liability''?', '["Owners must pay all of the business debts from their own savings","Owners can only lose the money they invested in the business","The business can only borrow a limited amount from banks","The business can only employ a limited number of workers"]'::jsonb, 'Shareholders'' personal assets are safe: they can only lose what they put in.', false, 'paper', '1.4 Types of business organisation', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, explanation = excluded.explanation, ref = excluded.ref, source = 'paper', battle_ok = false;
insert into question_keys (question_id, correct, guide) values ('95a1a2e7-fb5e-52f2-a553-e456aa46eea3', 1, 'Define it precisely, then contrast it if there are more marks: with unlimited liability (sole traders, most partnerships), personal possessions can be taken to pay business debts.') on conflict (question_id) do update set correct = excluded.correct, guide = excluded.guide;
